// Original teaching slides; figures are generated by the companion programs.
const fs = require("fs");
const path = require("path");
const PptxGenJS = require("pptxgenjs");
const JSZip = require("jszip");
const pptx = new PptxGenJS();
pptx.layout = "LAYOUT_WIDE";
pptx.author = "work_superconductor";
pptx.subject = "Fixed-gap spin-singlet BdG and an Al cutoff benchmark";
pptx.title = "BdG超导理论与计算入门";
pptx.lang = "zh-CN";
pptx.theme = { headFontFace: "Microsoft YaHei", bodyFontFace: "Microsoft YaHei",
               lang: "zh-CN" };
const C = { ink:"183B3C", teal:"117E83", pale:"EDF5F2", paper:"F7F4ED",
            coral:"C55B43", gold:"857140", muted:"546968", white:"FFFFFF" };
const S = pptx.ShapeType;
const ROOT = path.resolve(__dirname, "..");
let number = 0;

function text(s, content, x, y, w, h, options={}) {
  s.addText(content, {x,y,w,h,fontFace:"Microsoft YaHei",fontSize:19,
    color:C.ink,margin:0,breakLine:false,valign:"top",
    ...options});
}
function shape(s,type,x,y,w,h,fill,line=fill) {
  s.addShape(type,{x,y,w,h,fill:{color:fill},line:{color:line,width:1}});
}
function page(title, english, notes, dark=false) {
  const s = pptx.addSlide(); number++;
  s.background={color:dark?C.ink:C.paper};
  text(s,String(number).padStart(2,"0"),.55,.38,.55,.45,
       {fontFace:"Cambria",fontSize:18,color:dark?"9EC9BE":C.teal});
  text(s,title,1.18,.35,11.55,.6,{fontSize:32,bold:true,color:dark?C.white:C.ink});
  text(s,english,1.18,1.03,11.2,.38,{fontSize:13,color:dark?"B1CECA":C.muted});
  text(s,"work_superconductor  /  BdG 第二课  /  2026-10-03",.6,7.05,11.9,.2,
       {fontSize:10,color:dark?"B1CECA":C.muted});
  s.addNotes(notes);
  return s;
}
function card(s,title,body,x,y,w=3.9,h=3.4,color=C.teal) {
  shape(s,S.rect,x,y,w,h,C.white);
  shape(s,S.rect,x,y,.09,h,color);
  text(s,title,x+.25,y+.3,w-.5,.65,{fontSize:23,bold:true,color});
  text(s,body,x+.25,y+1.15,w-.5,h-1.35,{fontSize:18,breakLine:false});
}
function banner(s,message,y=6.35,color=C.teal) {
  shape(s,S.rect,.6,y,12.1,.48,C.pale);
  text(s,message,.8,y+.08,11.7,.3,{fontSize:15,color,bold:true});
}
function formula(s,content,x=1,y=2.0,w=11.2,h=1.25,size=34) {
  shape(s,S.roundRect,x,y,w,h,C.pale);
  text(s,content,x+.3,y+.25,w-.6,h-.35,
       {fontFace:"Cambria Math",fontSize:size,align:"center",valign:"mid"});
}
function image(s,relative,x,y,w,h) {
  const p = path.join(ROOT,relative), buf=fs.readFileSync(p);
  const width=buf.readUInt32BE(16), height=buf.readUInt32BE(20);
  const scale=Math.min(w/width,h/height), iw=width*scale, ih=height*scale;
  s.addImage({path:p,x:x+(w-iw)/2,y:y+(h-ih)/2,w:iw,h:ih});
}
function table(s,rows,x=.65,y=1.85,w=12.0,h=3.7,widths) {
  s.addTable(rows,{x,y,w,h,fontFace:"Microsoft YaHei",fontSize:18,
    border:{type:"solid",color:"D8E2DC",pt:.8},margin:.12,
    color:C.ink,fill:C.white,valign:"middle",colW:widths,
    autoPage:false,bold:false,
    rowH:.58});
}
function chain(s,periodic,y,color=C.teal) {
  const xs=[1.25,2.4,3.55,4.7,5.85,7.0];
  xs.forEach((x,i)=>{
    if(i) s.addShape(S.line,{x:xs[i-1]+.22,y:y+.2,w:x-xs[i-1]-.22,h:0,
                            line:{color,width:2.5}});
    shape(s,S.ellipse,x,y,.4,.4,color);
    text(s,String(i+1),x-.03,y+.52,.5,.35,{fontSize:14,align:"center"});
  });
  if(periodic) {
    s.addShape(S.line,{x:1.45,y:y-.45,w:5.75,h:0,line:{color:C.coral,width:2}});
    s.addShape(S.line,{x:1.45,y:y-.45,w:0,h:.45,line:{color:C.coral,width:2}});
    s.addShape(S.line,{x:7.2,y:y-.45,w:0,h:.45,line:{color:C.coral,width:2}});
  }
}

