(async()=>{
  if(number!==30) throw Error("Expected 30 slides");
  const file=path.join(__dirname,"BdG超导理论与计算入门.pptx");
  await pptx.writeFile({fileName:file});
  // Omit the optional registry that PptxGenJS places out of schema order.
  // Per-slide notes parts and their relationships remain intact.
  const zip=await JSZip.loadAsync(fs.readFileSync(file));
  const xml=await zip.file("ppt/presentation.xml").async("string");
  zip.file("ppt/presentation.xml",xml.replace(/<p:notesMasterIdLst>[\s\S]*?<\/p:notesMasterIdLst>/,""));
  fs.writeFileSync(file,await zip.generateAsync({type:"nodebuffer",compression:"DEFLATE"}));
  console.log("Built 30 slides with 30 detailed speaker notes: "+file);
})().catch(error=>{console.error(error);process.exit(1);});
